import{Ct as e,ct as t,lt as n,q as r}from"./chunks/framework.BVmwMUcr.js";var i=JSON.parse(`{"title":"Wushan Guide","description":"An overview of facilities at SCUT Wushan Campus","frontmatter":{"lang":"en-US","title":"Wushan Guide","description":"An overview of facilities at SCUT Wushan Campus","llm_translated":true},"headers":[],"relativePath":"en/infra/wushan/map.md","filePath":"en/infra/wushan/map.md","lastUpdated":1791510705000}`),a={name:`en/infra/wushan/map.md`};function o(r,i,a,o,s,c){return e(),t(`div`,null,[...i[0]||=[n(`<div style="display:none;" hidden="true" aria-hidden="true" data-nosnippet>Are you an LLM? You can read better optimized documentation at /en/infra/wushan/map.md for this page in Markdown format</div><h1 id="wushan-guide" tabindex="-1">Wushan Guide <a class="header-anchor" href="#wushan-guide" aria-label="Permalink to “Wushan Guide”">​</a></h1><h2 id="study-library-resources" tabindex="-1">Study &amp; Library Resources <a class="header-anchor" href="#study-library-resources" aria-label="Permalink to “Study &amp; Library Resources”">​</a></h2><h3 id="wushan-campus-library" tabindex="-1">Wushan Campus Library <a class="header-anchor" href="#wushan-campus-library" aria-label="Permalink to “Wushan Campus Library”">​</a></h3><ul><li><strong>Location</strong>: near the Sun Yat-sen statue and the East Gate</li><li><strong>Opening hours</strong>: opens and closes at fixed times; not open around the clock</li></ul><hr><p>TODO: Daily service points (parcel stations/print shops/hair salons/repair shops) and administrative offices (Academic Affairs Office/Student Affairs Department/Finance Office/Household Registration Office)</p><h2 id="sports-venues" tabindex="-1">Sports &amp; Venues <a class="header-anchor" href="#sports-venues" aria-label="Permalink to “Sports &amp; Venues”">​</a></h2><h3 id="daoming-swimming-hall" tabindex="-1">Daoming Swimming Hall <a class="header-anchor" href="#daoming-swimming-hall" aria-label="Permalink to “Daoming Swimming Hall”">​</a></h3><ul><li><strong>Location</strong>: inside Wushan Campus</li><li><strong>Type</strong>: heated indoor swimming hall</li><li><strong>Lanes</strong>: the practice area and the competition area are separate, each with 4 or more lanes</li><li><strong>Facilities</strong>: showers, lockers, and other basic amenities</li><li><strong>Fees</strong>: discounts for SCUT students</li><li><strong>Booking &amp; entry</strong>: handled through the WeChat mini program &quot;Hengsheng Sports Venues&quot; (恒生体育场馆)</li></ul><p>TODO: Badminton/table tennis/tennis court booking (smart service mini program), opening hours and fees for other sports venues</p><h2 id="dining-convenience-facilities" tabindex="-1">Dining &amp; Convenience Facilities <a class="header-anchor" href="#dining-convenience-facilities" aria-label="Permalink to “Dining &amp; Convenience Facilities”">​</a></h2><h3 id="canteens" tabindex="-1">Canteens <a class="header-anchor" href="#canteens" aria-label="Permalink to “Canteens”">​</a></h3><ul><li><strong>West District Canteen</strong>: serves morning tea (dim sum) and has round tables for large group meals</li><li><strong>Central District Canteen</strong>: counters for siu mei (Cantonese roast meats), fast food, and more</li><li><strong>South District Canteen</strong>: —</li><li><strong>North Canteen 1</strong>: its siu mei is famous throughout SCUT</li><li><strong>North Canteen 2</strong>: has a Yihetang drinks shop</li><li><strong>Fadiansuo Restaurant</strong>: more refined dishes at relatively higher prices</li></ul><h3 id="on-campus-supermarket" tabindex="-1">On-Campus Supermarket <a class="header-anchor" href="#on-campus-supermarket" aria-label="Permalink to “On-Campus Supermarket”">​</a></h3><ul><li><strong>Shengjia Supermarket</strong>: near North Canteen 2</li></ul>`,16)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};